using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    #region AddItem Tests

    [TestMethod]
    public void AddItem_SingleItem_ItemIsAddedToCart()
    {
        // Arrange
        string sku = "SKU-001";
        int quantity = 2;
        decimal price = 9.99m;

        // Act
        _cart.AddItem(sku, quantity, price);

        // Assert — verify via total calculation
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(19.98m, total);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_AllItemsInCart()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 2, 5.00m);
        _cart.AddItem("SKU-003", 3, 3.00m);

        // Assert
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(29.00m, total); // 10 + 10 + 9
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantityIsAccumulated()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 3, 10.00m);

        // Assert — total should reflect combined quantity of 5
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(50.00m, total);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        // Arrange, Act & Assert
        Assert.ThrowsException<ArgumentException>(() =>
            _cart.AddItem(sku!, 1, 10.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100)]
    public void AddItem_ZeroOrNegativeQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        // Arrange, Act & Assert
        Assert.ThrowsException<ArgumentOutOfRangeException>(() =>
            _cart.AddItem("SKU-001", quantity, 10.00m));
    }

    [TestMethod]
    [DataRow(-0.01)]
    [DataRow(-99.99)]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException(double price)
    {
        // Arrange, Act & Assert
        Assert.ThrowsException<ArgumentOutOfRangeException>(() =>
            _cart.AddItem("SKU-001", 1, (decimal)price));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        // Arrange & Act — free items should be allowed
        _cart.AddItem("FREE-ITEM", 1, 0.00m);

        // Assert
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(0.00m, total);
    }

    #endregion

    #region RemoveItem Tests

    [TestMethod]
    public void RemoveItem_ExistingItem_ItemIsRemovedFromCart()
    {
        // Arrange
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-002", 1, 5.00m);

        // Act
        _cart.RemoveItem("SKU-001");

        // Assert — only SKU-002 remains
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(5.00m, total);
    }

    [TestMethod]
    public void RemoveItem_OnlyItemInCart_CartBecomesEmpty()
    {
        // Arrange
        _cart.AddItem("SKU-001", 3, 7.50m);

        // Act
        _cart.RemoveItem("SKU-001");

        // Assert
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(0.00m, total);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        // Arrange
        _cart.AddItem("SKU-001", 1, 10.00m);

        // Act & Assert
        Assert.ThrowsException<InvalidOperationException>(() =>
            _cart.RemoveItem("SKU-MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void RemoveItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        // Arrange, Act & Assert
        Assert.ThrowsException<ArgumentException>(() =>
            _cart.RemoveItem(sku!));
    }

    #endregion

    #region CalculateTotal Tests

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        // Arrange — fresh cart, no items

        // Act
        decimal total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(0.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        // Arrange
        _cart.AddItem("SKU-001", 4, 2.50m);

        // Act
        decimal total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(10.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAllLineItems()
    {
        // Arrange
        _cart.AddItem("SKU-001", 2, 15.00m); // 30.00
        _cart.AddItem("SKU-002", 1, 7.50m);  // 7.50
        _cart.AddItem("SKU-003", 5, 1.20m);  // 6.00

        // Act
        decimal total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(43.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ReflectsRemainingItems()
    {
        // Arrange
        _cart.AddItem("SKU-001", 2, 10.00m); // 20.00
        _cart.AddItem("SKU-002", 1, 5.00m);  // 5.00
        _cart.RemoveItem("SKU-002");

        // Act
        decimal total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(20.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_LargeQuantityAndPrice_HandlesLargeValues()
    {
        // Arrange
        _cart.AddItem("EXPENSIVE", 1000, 999.99m);

        // Act
        decimal total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(999_990.00m, total);
    }

    #endregion

    #region ApplyCoupon Tests

    [TestMethod]
    public void ApplyCoupon_ValidCoupon_ReducesTotal()
    {
        // Arrange
        _cart.AddItem("SKU-001", 2, 50.00m); // 100.00 total

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert — coupon should reduce the total
        decimal total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, $"Expected total less than 100.00 after coupon, but got {total}");
    }

    [TestMethod]
    public void ApplyCoupon_ValidPercentageCoupon_AppliesPercentageDiscount()
    {
        // Arrange
        _cart.AddItem("SKU-001", 1, 200.00m);

        // Act
        _cart.ApplyCoupon("PERCENT20");

        // Assert — 20% off 200 = 160
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(160.00m, total);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ApplyCoupon_NullOrEmptyCode_ThrowsArgumentException(string? code)
    {
        // Arrange, Act & Assert
        Assert.ThrowsException<ArgumentException>(() =>
            _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCouponCode_ThrowsInvalidOperationException()
    {
        // Arrange
        _cart.AddItem("SKU-001", 1, 50.00m);

        // Act & Assert
        Assert.ThrowsException<InvalidOperationException>(() =>
            _cart.ApplyCoupon("NOTREAL"));
    }

    [TestMethod]
    public void ApplyCoupon_MultipleCoupons_AppliesBothDiscounts()
    {
        // Arrange
        _cart.AddItem("SKU-001", 4, 25.00m); // 100.00

        // Act
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("EXTRA5");

        // Assert — both coupons should reduce the total further
        decimal total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, $"Expected total less than 100.00 after coupons, but got {total}");
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_DoesNotThrow()
    {
        // Arrange — empty cart

        // Act & Assert — applying coupon to empty cart should not crash
        _cart.ApplyCoupon("SAVE10");
        decimal total = _cart.CalculateTotal();
        Assert.AreEqual(0.00m, total);
    }

    #endregion
}

